    }
    class MatchingStrategy {
        <<interface>>
        +match(TripRequest, List~Driver~) Optional~Driver~
    }
    class PricingStrategy {
        <<interface>>
        +calculate(TripRequest, Driver) Fare
    }
    class LocationObserver {
        <<interface>>
